package tv.vela.launcher;

import android.app.*;import android.content.*;import android.graphics.*;import android.os.*;import android.view.*;import android.widget.*;import java.io.*;import java.lang.reflect.*;import java.util.*;

/** Actual player chrome with explicit demo metadata on an owned emulator. No stream or tuner is started. */
public final class AndroidUpNextTest extends Instrumentation {
    private Activity activity;private LiveTvPlayer player;
    Object field(Object object,String name)throws Exception{Field f=object.getClass().getDeclaredField(name);f.setAccessible(true);return f.get(object);}
    void check(boolean value,String why){if(!value)throw new AssertionError(why);}
    void ui(Runnable run){runOnMainSync(run);waitForIdleSync();}
    void capture()throws Exception{Bitmap b=getUiAutomation().takeScreenshot();check(b!=null&&b.getWidth()==3840&&b.getHeight()==2160,"Native 4K capture required");try(OutputStream out=new FileOutputStream(new File(getTargetContext().getExternalFilesDir(null),"player-up-next-demo.png"))){b.compress(Bitmap.CompressFormat.PNG,100,out);}finally{b.recycle();}}
    public void onCreate(Bundle args){super.onCreate(args);start();}
    public void onStart(){Bundle result=new Bundle();Context c=getTargetContext();SharedPreferences preferences=Updates.prefs(c);Map<String,?> saved=new HashMap<>(preferences.getAll());try{
        check(Build.FINGERPRINT.contains("generic")||Build.MODEL.contains("sdk"),"Owned emulator required");check(!new PlexClient(c).connected()&&!new JellyfinClient(c).connected()&&!new XtreamClient(c).connected(),"Clean account state required");preferences.edit().putBoolean("automatic",false).commit();
        for(int api:new int[]{26,28,29,36}){Bitmap shade=Bitmap.createBitmap(2,360,Bitmap.Config.ARGB_8888);android.graphics.drawable.GradientDrawable background=VelaPlayerUi.shade(api);background.setBounds(0,0,2,360);background.draw(new Canvas(shade));check(Color.alpha(shade.getPixel(1,0))<15&&Color.alpha(shade.getPixel(1,120))>=225&&Color.alpha(shade.getPixel(1,359))>=250,"Player shade loses contrast or transparency for API "+api);shade.recycle();}
        activity=startActivitySync(new Intent(c,SettingsActivity.class).putExtra("fromSetup",true).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));FrameLayout root=new FrameLayout(activity);ui(()->{activity.setContentView(root);player=new LiveTvPlayer(activity,new LiveTvPlayer.Actions(){public void back(){}public void zap(int n){}public void channels(int p){}public void choose(LiveTvData.Channel ch){}});root.addView(player,new FrameLayout.LayoutParams(-1,-1));player.select(new LiveTvData.Channel("demo","Canal · Demo","Demo","",Collections.emptyList()));});
        long now=System.currentTimeMillis()/1000;LiveTvData.Programme current=new LiveTvData.Programme(now-1800,now+900,"El mundo desde el aire"),next=new LiveTvData.Programme(now+900,now+4500,"Rutas por el Mediterráneo");ui(()->player.metadata(current,next));UpNextView tile=(UpNextView)field(player,"nextProgramme");TextView name=(TextView)field(tile,"title"),time=(TextView)field(tile,"time");check(tile.isShown()&&name.getText().toString().equals(next.title)&&time.getText().toString().contains("–"),"Following programme or schedule missing");Rect left=new Rect(),right=new Rect();((View)field(player,"programme")).getGlobalVisibleRect(left);tile.getGlobalVisibleRect(right);check(left.right<=right.left,"Current and following programme overlap");check(!tile.hasFocusable()&&player.player==null&&player.tuner==null,"Metadata allocated playback or captured remote focus");ui(()->{try{((View)field(player,"intro")).setVisibility(View.GONE);}catch(Exception e){throw new RuntimeException(e);}});capture();
        for(LiveTvData.Programme invalid:new LiveTvData.Programme[]{null,new LiveTvData.Programme(now-60,now+60,"Old"),new LiveTvData.Programme(now+900,now+900,"Invalid"),new LiveTvData.Programme(now+900,now+1800," "),new LiveTvData.Programme(now+60,now+1800,"Overlapping")}){ui(()->player.metadata(current,invalid));check(tile.getVisibility()==View.GONE&&name.getText().length()==0&&time.getText().length()==0,"Missing/invalid EPG left a stale following programme");}
        ui(()->player.metadata(null,next));check(tile.isShown(),"Following programme hidden when current programme is unknown");ui(()->{root.removeView(player);root.addView(player,new FrameLayout.LayoutParams(1280,720));player.metadata(current,next);});for(int n=0;n<60;n++){waitForIdleSync();((View)field(player,"programme")).getGlobalVisibleRect(left);tile.getGlobalVisibleRect(right);if(right.width()>0&&left.right<=right.left&&right.right<=1280)break;Thread.sleep(30);}check(right.width()>0&&left.right<=right.left&&right.right<=1280,"Following programme layout failed at 720p: "+left+" / "+right+"; viewport="+player.getWidth()+"x"+player.getHeight());
        LiveTvLogos.LogoView logo=(LiveTvLogos.LogoView)field(player,"channelLogo");Bitmap light=Bitmap.createBitmap(16,16,Bitmap.Config.ARGB_8888),dark=Bitmap.createBitmap(16,16,Bitmap.Config.ARGB_8888);light.eraseColor(Color.WHITE);dark.eraseColor(Color.BLACK);ui(()->logo.setImageBitmap(light));check(((android.graphics.drawable.GradientDrawable)logo.getBackground()).getColor().getDefaultColor()==VelaTheme.CARD,"White logo lost its dark plate");ui(()->logo.setImageBitmap(dark));check(((android.graphics.drawable.GradientDrawable)logo.getBackground()).getColor().getDefaultColor()==0xFFF0F1F6,"Dark logo lost contrast");ui(()->logo.setImageDrawable(null));light.recycle();dark.recycle();
        final VelaPlaybackPanel[] menu={null};ui(()->{root.removeView(player);root.addView(player,new FrameLayout.LayoutParams(-1,-1));menu[0]=new VelaPlaybackPanel(activity,"Canal · Demo",()->Arrays.asList(new VelaPlaybackPanel.Item("Audio","",()->{}),new VelaPlaybackPanel.Item("Signal","1920 × 1080",null),new VelaPlaybackPanel.Item("Picture","",()->{})),()->{});root.addView(menu[0],new FrameLayout.LayoutParams(-1,-1));});java.util.List<View> actions=(java.util.List<View>)field(menu[0],"buttons");check(actions.size()==2&&actions.get(0).hasFocus(),"Informational controls captured the remote");ui(()->menu[0].remote(new KeyEvent(KeyEvent.ACTION_DOWN,KeyEvent.KEYCODE_DPAD_DOWN)));check(actions.get(1).hasFocus(),"Arrow navigation stopped on an informational row");ui(()->menu[0].remote(new KeyEvent(KeyEvent.ACTION_DOWN,KeyEvent.KEYCODE_MENU)));check(menu[0].getParent()==null,"Menu did not dismiss the controls");
        ui(()->player.select(new LiveTvData.Channel("other","Otro canal · Demo","Demo","",Collections.emptyList())));check(tile.getVisibility()==View.GONE&&name.getText().length()==0,"Channel change retained the previous programme");result.putString("result","PASS shared following-programme tile, title/schedule, missing/invalid/past/overlapping guide data, unknown current programme, channel-change clearing, separate columns at 4K/720p, no remote focus or decoder allocation. Native adaptive white/dark logo contrast and non-interactive signal rows verified. One native demo capture; no signal played.");
    }catch(Throwable failure){result.putString("error",android.util.Log.getStackTraceString(failure));}finally{if(activity!=null)ui(()->{if(player!=null)player.pause();activity.finish();});SharedPreferences.Editor edit=preferences.edit().clear();for(Map.Entry<String,?> e:saved.entrySet()){Object v=e.getValue();if(v instanceof Boolean)edit.putBoolean(e.getKey(),(Boolean)v);else if(v instanceof String)edit.putString(e.getKey(),(String)v);else if(v instanceof Long)edit.putLong(e.getKey(),(Long)v);else if(v instanceof Integer)edit.putInt(e.getKey(),(Integer)v);}edit.commit();}finish(result.containsKey("error")?1:-1,result);}
}
